def linear_search(items, target):
    for i, x in enumerate(items):
        if x == target:
            return i
    return -1

print(linear_search([7, 3, 9, 4], 9), linear_search([7, 3, 9, 4], 5))   # 2 -1

def binary_search(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2      # avoids overflow in fixed-width integers
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

data = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
print(binary_search(data, 23), binary_search(data, 7))   # 5 -1

def interpolation_search(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi and a[lo] <= target <= a[hi]:
        if a[hi] == a[lo]:
            return lo if a[lo] == target else -1
        pos = lo + (target - a[lo]) * (hi - lo) // (a[hi] - a[lo])
        if a[pos] == target:
            return pos
        if a[pos] < target:
            lo = pos + 1
        else:
            hi = pos - 1
    return -1

data = list(range(0, 1000, 10))              # evenly spread
print(interpolation_search(data, 730))       # 73

def build_table(p):
    table, k = [0] * len(p), 0
    for i in range(1, len(p)):
        while k and p[i] != p[k]:
            k = table[k - 1]
        if p[i] == p[k]:
            k += 1
        table[i] = k
    return table

def kmp_search(text, p):
    table, k, hits = build_table(p), 0, []
    for i, ch in enumerate(text):
        while k and ch != p[k]:
            k = table[k - 1]
        if ch == p[k]:
            k += 1
        if k == len(p):
            hits.append(i - k + 1)
            k = table[k - 1]
    return hits

print(build_table("ABABC"))                 # [0, 0, 1, 2, 0]
print(kmp_search("ABABABCABABC", "ABABC"))  # [2, 7]

def fact(n):                       # not a tail call: multiply after the call returns
    return 1 if n == 0 else n * fact(n - 1)

def fact_tail(n, acc=1):           # a tail call: nothing left to do after it
    return acc if n == 0 else fact_tail(n - 1, acc * n)

def fact_loop(n):                  # what tail-call optimization turns it into
    acc = 1
    while n > 0:
        acc, n = acc * n, n - 1
    return acc

print(fact(10), fact_tail(10), fact_loop(10))    # 3628800 3628800 3628800

from functools import lru_cache
import time

def fib_slow(n):
    return n if n < 2 else fib_slow(n - 1) + fib_slow(n - 2)

@lru_cache(maxsize=None)
def fib_memo(n):
    return n if n < 2 else fib_memo(n - 1) + fib_memo(n - 2)

def fib_loop(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

start = time.perf_counter(); print(fib_slow(27), round(time.perf_counter() - start, 2), "s")
print(fib_memo(90), fib_loop(90))     # 2880067194370816120 2880067194370816120

from functools import lru_cache

calls = 0

@lru_cache(maxsize=None)
def paths(r, c):                 # routes across a grid moving only right or down
    global calls
    calls += 1
    if r == 0 or c == 0:
        return 1
    return paths(r - 1, c) + paths(r, c - 1)

print(paths(16, 16), "routes,", calls, "calls")   # 601080390 routes, 288 calls

def knapsack(items, capacity):
    best = [0] * (capacity + 1)                 # best[w] = best value at capacity w
    for weight, value in items:
        for w in range(capacity, weight - 1, -1):
            best[w] = max(best[w], best[w - weight] + value)
    return best[capacity]

items = [(1, 1), (3, 4), (4, 5), (5, 7)]         # (weight, value)
print(knapsack(items, 7))                        # 9: take the weight-3 and weight-4 items

def lcs(a, b):
    table = [[""] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            if x == y:
                table[i + 1][j + 1] = table[i][j] + x
            else:
                table[i + 1][j + 1] = max(table[i][j + 1], table[i + 1][j], key=len)
    return table[-1][-1]

result = lcs("ABCBDAB", "BDCABA")
print(result, len(result))       # a common subsequence of length 4, such as BCBA
